DROP TABLE IF EXISTS `payroll`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payroll` (
  `id` int NOT NULL AUTO_INCREMENT,
  `employee_id` int NOT NULL,
  `month` int NOT NULL,
  `year` int NOT NULL,
  `work_days` decimal(5,2) NOT NULL DEFAULT '0.00',
  `gross_income` decimal(18,2) NOT NULL DEFAULT '0.00',
  `bonus` decimal(18,2) NOT NULL DEFAULT '0.00',
  `income_detail` text COLLATE utf8mb4_unicode_ci,
  `bhxh` decimal(18,2) NOT NULL DEFAULT '0.00',
  `bhyt` decimal(18,2) NOT NULL DEFAULT '0.00',
  `bhtn` decimal(18,2) NOT NULL DEFAULT '0.00',
  `employer_insurance` decimal(18,2) NOT NULL DEFAULT '0.00',
  `taxable_income` decimal(18,2) NOT NULL DEFAULT '0.00',
  `pit` decimal(18,2) NOT NULL DEFAULT '0.00',
  `other_deduction` decimal(18,2) NOT NULL DEFAULT '0.00',
  `net_salary` decimal(18,2) NOT NULL DEFAULT '0.00',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Nháp',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_pay` (`employee_id`,`month`,`year`),
  CONSTRAINT `payroll_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
